# choose highest visible revision per event_id
chosen={}
for r in visible:
    eid=r['event_id']
    if eid not in chosen or r['revision']>chosen[eid]['revision']:
        chosen[eid]=r
chosen_list=[r for r in chosen.values() if r['event_time']<=target_time]
chosen_list_sorted=sorted(chosen_list,key=lambda r:(r['event_time'],r['event_id']))
